#!/usr/bin/env bash
# Première connexion + chapitre « Le profil et la première connexion » :
#   - un nouveau membre est ramené sur son profil tant qu'il n'a pas remplacé le mot de passe
#     provisoire (l'e-mail de bienvenue l'annonçait, rien ne l'imposait) ;
#   - après enregistrement, la session est relue (plus de retour forcé sur /profil/edit,
#     nom à jour dans le header) ; encadré d'accueil en première connexion ;
#   - users.updateProfile supprimé (inutilisé, renvoyait l'empreinte du mot de passe) ;
#   - nouveau chapitre (partie Membres et collaboration).
# Prérequis : apply-reglages-site.sh.
# Usage (racine du repo) : bash apply-premiere-connexion.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/membres/profil-et-premiere-connexion.mdx" 2>/dev/null | grep -qF "title: \"Le profil et la première connexion\""; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "title: \"Les réglages du site\"" "apps/web/content/docs/dev/contenu/reglages-du-site.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-reglages-site.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/auth/authentification.mdx" "apps/web/content/docs/dev/index.mdx" "apps/web/src/features/admin/users/forms/update-me/UpdateMeForm.tsx" "apps/web/src/features/admin/users/forms/update-me/updateMeForm.action.ts" "apps/web/src/features/auth/ChangePasswordForm.tsx" "apps/web/src/features/auth/FirstLoginRedirect.tsx" "packages/backend/src/modules/auth/router.ts" "packages/backend/src/modules/users/router.ts" "prisma/schema.prisma")
CREATED=("apps/web/content/docs/dev/membres/profil-et-premiere-connexion.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "apps/web/content/docs/dev/membres" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "title: \"Le profil et la première connexion\"" "apps/web/content/docs/dev/membres/profil-et-premiere-connexion.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/membres"
