trap - ERR

[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm --filter backend typecheck && pnpm typecheck"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; exit 1
fi
echo "  ✅ check OK"
git add "${MODIFIED[@]}" "${CREATED[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
première connexion : le mot de passe provisoire doit être remplacé ; doc « Le profil et la première connexion »

- isFirstLogin = mot de passe provisoire actif : levé par auth.changePassword
  (et la réinitialisation), plus par l'enregistrement du profil — l'e-mail de
  bienvenue l'annonçait, rien ne l'imposait.
- Formulaires profil et mot de passe : relecture de la session du store après
  écriture (sinon FirstLoginRedirect ramenait sur /profil/edit et le header
  gardait l'ancien nom) ; encadré d'accueil en première connexion.
- users.updateProfile supprimé (inutilisé ; renvoyait la ligne User complète,
  empreinte du mot de passe comprise).
- Doc : chapitre 9.1 ; chapitre auth et sommaire à jour.

